BEGIN;
SELECT set_config('request.jwt.claim.sub','92000000-0000-4000-8000-000000000099',true);
DO $$ DECLARE shop uuid; ingredient uuid; supplier uuid; po uuid; pending jsonb; result jsonb; reopening uuid:=gen_random_uuid(); closed_revision bigint;
BEGIN
 INSERT INTO restaurants(name,slug,brand_id,tax_entity_id) VALUES('Closure branch','closure-branch-'||gen_random_uuid(),'91000000-0000-4000-8000-000000000003','91000000-0000-4000-8000-000000000004') RETURNING id INTO shop;
 ASSERT admin_get_store_closure_readiness_v1(shop)->>'ready'='true';
 INSERT INTO inventory_suppliers(brand_id,supplier_name) VALUES('91000000-0000-4000-8000-000000000003','Closure supplier') RETURNING id INTO supplier;
 PERFORM set_config('app.procurement_write','true',true);
 INSERT INTO inventory_purchase_orders(purchase_order_no,restaurant_id,supplier_id,workflow_version,status) VALUES('CLOSE-'||gen_random_uuid(),shop,supplier,2,'draft') RETURNING id INTO po;
 pending:=admin_get_store_closure_readiness_v1(shop);
 ASSERT pending->'pending'->>'purchase_orders'='1';
 BEGIN PERFORM admin_close_store(shop,'Should remain open with unfinished PO'); RAISE EXCEPTION 'closed with PO'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='STORE_CLOSURE_PENDING',SQLERRM; END;
 BEGIN PERFORM admin_deactivate_restaurant(shop); RAISE EXCEPTION 'legacy bypass closed'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='STORE_CLOSURE_PENDING',SQLERRM; END;
 BEGIN UPDATE restaurants SET is_active=false WHERE id=shop; RAISE EXCEPTION 'direct write bypass closed'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='STORE_CLOSURE_PENDING',SQLERRM; END;
 ASSERT (SELECT is_active FROM restaurants WHERE id=shop);
 UPDATE inventory_purchase_orders SET status='cancelled' WHERE id=po;
 result:=admin_close_store(shop,'All pending work settled in isolated fixture');
 ASSERT (SELECT NOT is_active FROM restaurants WHERE id=shop);
 ASSERT (SELECT state='closed' FROM store_lifecycle WHERE restaurant_id=shop);
 ASSERT EXISTS(SELECT 1 FROM inventory_purchase_orders WHERE id=po AND status='cancelled'),'historical order removed';
 BEGIN INSERT INTO inventory_purchase_orders(purchase_order_no,restaurant_id,supplier_id,workflow_version,status) VALUES('CLOSE-'||gen_random_uuid(),shop,supplier,2,'draft'); RAISE EXCEPTION 'closed store accepted PO'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='STORE_CLOSED_FOR_NEW_PROCUREMENT',SQLERRM; END;
 BEGIN UPDATE restaurants SET is_active=true WHERE id=shop; RAISE EXCEPTION 'closed store reopened without preparation'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='STORE_REOPEN_REQUIRES_PREPARATION',SQLERRM; END;
 SELECT revision INTO closed_revision FROM store_lifecycle WHERE restaurant_id=shop;
 result:=admin_prepare_store_reopening_v1(reopening,shop,closed_revision,'Prepare the same store for reopening');
 PERFORM admin_prepare_store_reopening_v1(reopening,shop,closed_revision,'Prepare the same store for reopening');
 ASSERT result->'lifecycle'->>'state'='preparing';
 ASSERT result->>'business_ready'='false';
 ASSERT (SELECT is_active FROM restaurants WHERE id=shop);
 ASSERT (SELECT count(*)=1 FROM store_reopening_events WHERE id=reopening);
 BEGIN INSERT INTO orders(restaurant_id,status) VALUES(shop,'pending'); RAISE EXCEPTION 'reopen bypassed preparation'; EXCEPTION WHEN raise_exception THEN ASSERT SQLERRM='STORE_NOT_OPEN_FOR_NEW_ORDERS',SQLERRM; END;
END $$;
SELECT 'STORE_CLOSURE=PASS pending PO blocks explicit, legacy and direct closure; history preserved; new procurement blocked';
ROLLBACK;
